-- 0116 Contractor commercial payables & private settlement chain.
-- Rates are snapshotted at preparation; later rate edits cannot rewrite history.
CREATE TABLE `contractorPayables` (`id` int NOT NULL AUTO_INCREMENT,`payableRef` varchar(80) NOT NULL,`chainRef` varchar(80) NOT NULL,`payerOrgRef` varchar(40) NOT NULL,`payeeOrgRef` varchar(40) NOT NULL,`rateRef` varchar(80) NOT NULL,`compensationType` enum('HOURLY','SALARY','DAY_RATE','LOAD_RATE','KM_RATE','PERCENTAGE','PIECE_RATE','CONTRACT_RATE') NOT NULL,`quantityMillis` int NOT NULL,`quantityUnit` enum('HOUR','DAY','LOAD','KM','PERCENT','PIECE','CONTRACT') NOT NULL,`rateCentsSnapshot` int NOT NULL,`grossAmountCents` int NOT NULL,`currency` varchar(3) NOT NULL DEFAULT 'CAD',`evidenceRefsJson` text NOT NULL,`preparationSource` enum('HUMAN','AI_SECRETARY') NOT NULL DEFAULT 'HUMAN',`state` enum('prepared','review','approved','posted','paid','disputed','void') NOT NULL DEFAULT 'prepared',`preparedByUserId` int NOT NULL,`approvedByUserId` int NULL,`approvedAt` timestamp NULL,`postedAt` timestamp NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `contractorPayables_payableRef_unique` (`payableRef`),KEY `contractorPayables_payer_idx` (`payerOrgRef`,`state`),KEY `contractorPayables_payee_idx` (`payeeOrgRef`,`state`),KEY `contractorPayables_chain_idx` (`chainRef`,`state`));
CREATE TABLE `contractorPayableEvents` (`id` int NOT NULL AUTO_INCREMENT,`eventRef` varchar(80) NOT NULL,`payableRef` varchar(80) NOT NULL,`actorOrgRef` varchar(40) NOT NULL,`actorUserId` int NOT NULL,`eventType` enum('PREPARED','SUBMITTED_REVIEW','APPROVED','POSTED','PAID','DISPUTED','VOIDED') NOT NULL,`amountCentsSnapshot` int NOT NULL,`note` varchar(500) NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `contractorPayableEvents_eventRef_unique` (`eventRef`),KEY `contractorPayableEvents_payable_idx` (`payableRef`,`createdAt`));
